import type { CSSProperties, ReactNode } from "react";
import { isTodo, type BotColor, type Maybe } from "../content";

export function cx(...parts: (string | false | null | undefined)[]) {
  return parts.filter(Boolean).join(" ");
}

/** Muted pill shown wherever content.ts still has a placeholder. */
export function Soon({ note, className }: { note?: string; className?: string }) {
  return (
    <span
      title={note}
      className={cx(
        "inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border border-dashed border-line bg-muted px-2.5 py-0.5 text-xs font-medium text-muted-fg",
        className,
      )}
    >
      <span aria-hidden className="size-1.5 rounded-full bg-muted-fg/60" />
      Coming soon
    </span>
  );
}

/** Renders a value, or the Coming soon pill if it is still a placeholder. */
export function Show<T>({
  value,
  children,
  className,
}: {
  value: Maybe<T>;
  children?: (v: T) => ReactNode;
  className?: string;
}) {
  if (isTodo(value)) return <Soon note={value.todo} className={className} />;
  return <>{children ? children(value) : String(value)}</>;
}

export function ExtLink({
  href,
  children,
  className,
}: {
  href: Maybe<string>;
  children: ReactNode;
  className?: string;
}) {
  if (isTodo(href)) return <Soon note={href.todo} className={className} />;
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer"
      className={cx("font-medium text-link underline-offset-4 hover:underline", className)}
    >
      {children}
    </a>
  );
}

/** A simple bot face: colored circle with two eyes. */
export function BotFace({
  color,
  size = 40,
  className,
}: {
  color: BotColor;
  size?: number;
  className?: string;
}) {
  const style = { width: size, height: size, background: `var(--bot-${color})` } as CSSProperties;
  const eye = Math.max(4, Math.round(size * 0.2));
  const pupil = Math.max(2, Math.round(eye * 0.45));
  return (
    <span
      aria-hidden
      style={style}
      className={cx(
        "relative inline-flex shrink-0 items-center justify-center gap-[14%] rounded-full shadow-[inset_0_-3px_0_rgb(0_0_0/0.15)]",
        className,
      )}
    >
      {[0, 1].map((i) => (
        <span
          key={i}
          className="eye flex items-center justify-center rounded-full bg-white"
          style={{ width: eye, height: eye, marginTop: -size * 0.06 }}
        >
          <span
            className="rounded-full bg-[#0b0c0e]"
            style={{ width: pupil, height: pupil, transform: "translate(15%, 10%)" }}
          />
        </span>
      ))}
    </span>
  );
}

export function Container({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cx("mx-auto w-full max-w-6xl px-4 sm:px-6", className)}>{children}</div>;
}

export function Section({
  id,
  title,
  intro,
  children,
  className,
}: {
  id?: string;
  title: string;
  intro?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  const headingId = id ? `${id}-title` : undefined;
  return (
    <section id={id} aria-labelledby={headingId} className={cx("py-20 sm:py-28", className)}>
      <Container>
        <h2
          id={headingId}
          className="max-w-3xl text-3xl font-semibold tracking-[-0.03em] text-balance sm:text-[2.75rem] sm:leading-[1.08]"
        >
          {title}
        </h2>
        {intro && <p className="mt-4 max-w-[62ch] text-lg text-muted-fg text-pretty">{intro}</p>}
        <div className="mt-12">{children}</div>
      </Container>
    </section>
  );
}

export function Button({
  href,
  children,
  variant = "primary",
  icon,
}: {
  href: string;
  children: ReactNode;
  variant?: "primary" | "ghost";
  icon?: ReactNode;
}) {
  return (
    <a
      href={href}
      className={cx(
        "inline-flex h-11 items-center gap-2 rounded-full px-5 text-[15px] font-medium transition-colors duration-150",
        variant === "primary"
          ? "bg-primary text-primary-fg hover:opacity-90"
          : "border border-line bg-card text-fg hover:bg-accent",
      )}
    >
      {icon}
      {children}
    </a>
  );
}
import { Check, ShieldQuestion, X } from "lucide-react";
import { useState } from "react";
import { approvalExample, caps, isTodo, receiptExample } from "../content";
import { BotFace, ExtLink, Show, cx } from "./ui";

/** Interactive mock of the inline Approve/Deny card. */
export function ApprovalCard({ compact = false }: { compact?: boolean }) {
  const [state, setState] = useState<"pending" | "approved" | "denied">("pending");
  const a = approvalExample;
  return (
    <div className="rounded-2xl border border-line bg-card p-4 shadow-[0_1px_0_rgb(0_0_0/0.03)] sm:p-5">
      <div className="flex items-center gap-3">
        <BotFace color="violet" size={30} />
        <div className="min-w-0 text-sm leading-tight">
          <p className="font-medium">{a.agent} wants to run a tool</p>
          <p className="text-muted-fg">Asked by {a.via}</p>
        </div>
        <ShieldQuestion aria-hidden className="ml-auto size-5 shrink-0 text-warn" />
      </div>
      <div className="mt-4 overflow-x-auto rounded-xl bg-muted px-3.5 py-3 text-[13px] leading-relaxed">
        <p className="font-semibold">{a.tool}</p>
        <dl className="mt-1 grid grid-cols-[auto_1fr] gap-x-3">
          {Object.entries(a.args).map(([k, v]) => (
            <div key={k} className="contents">
              <dt className="text-muted-fg">{k}</dt>
              <dd className="break-words">{v}</dd>
            </div>
          ))}
        </dl>
      </div>
      <div className="mt-4 flex min-h-10 items-center gap-2" aria-live="polite">
        {state === "pending" ? (
          <>
            <button
              type="button"
              onClick={() => setState("approved")}
              className="inline-flex h-9 items-center gap-1.5 rounded-full bg-primary px-4 text-sm font-medium text-primary-fg transition-opacity hover:opacity-90"
            >
              <Check aria-hidden className="size-4" /> Approve
            </button>
            <button
              type="button"
              onClick={() => setState("denied")}
              className="inline-flex h-9 items-center gap-1.5 rounded-full border border-line px-4 text-sm font-medium transition-colors hover:bg-accent"
            >
              <X aria-hidden className="size-4" /> Deny
            </button>
          </>
        ) : (
          <p className={cx("pop flex items-center gap-2 text-sm", state === "approved" ? "text-ok" : "text-bad")}>
            {state === "approved" ? (
              <>
                <Check aria-hidden className="size-4" /> Approved. {a.agent} runs the tool and the reply continues.
              </>
            ) : (
              <>
                <X aria-hidden className="size-4" /> Denied. The tool never runs.
              </>
            )}
            <button
              type="button"
              onClick={() => setState("pending")}
              className="ml-1 text-muted-fg underline underline-offset-4 hover:text-fg"
            >
              Reset
            </button>
          </p>
        )}
      </div>
      {!compact && <p className="mt-3 text-xs text-muted-fg">Illustration. Try the buttons.</p>}
    </div>
  );
}

function money(n: number) {
  return `$${n < 0.01 ? n.toFixed(4) : n.toFixed(2)}`;
}

