  const title = `${a.agent} wants to run: ${a.label}`;
  return (
    <div
      role="group"
      aria-label={title}
      className="flex max-w-full flex-col gap-2 rounded-[20px] border border-line bg-muted/60 px-[18px] py-3 text-[14.5px] leading-[1.45]"
