  );
}

export function CopyCommand({ label, cmd }: { label: string; cmd: string }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(cmd);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch {
      /* clipboard unavailable: the command is still selectable */
    }
  };
  return (
    <div className="min-w-0 rounded-xl border border-line bg-card">
      <div className="flex items-center justify-between gap-3 px-4 pt-3 text-sm text-muted-fg">
        <span>{label}</span>
        <button
          type="button"
          onClick={copy}
          className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium text-fg transition-colors hover:bg-accent"
          aria-label={`Copy command: ${label}`}
        >
          {copied ? <Check aria-hidden className="size-3.5 text-ok" /> : <Copy aria-hidden className="size-3.5" />}
          <span aria-live="polite">{copied ? "Copied" : "Copy"}</span>
        </button>
      </div>
      <pre className="overflow-x-auto px-4 pb-3 pt-2 text-[13px] leading-relaxed">
        <code className="font-mono">
          <span aria-hidden className="select-none text-muted-fg">$ </span>
          {cmd}
        </code>
      </pre>
    </div>
  );
}
import neatlogsLogo from "@/assets/neatlogs-nl.png?inline";
import { resolvePersonaColorDef, SHIPPED_BOT_AVATAR_SHAPE_KEYS, shippedHash } from "@/lib/avatar";

/**
 * BotAvatar's `color` prop is rakazo's stored avatar value: "<hex>", "<hex>::shape_<n>" or a
 * `data:image/` URI (the only image form BotAvatar renders; Vite's `?inline` bundles ours as one).
 * An empty value falls back to one fixed orange (so every agent looked the same), which is
 * why each agent gets an explicit value here: a curated color + mascot shape for our known
 * agents, and a value derived from the id for anything else.
 */
const CURATED: Record<string, string> = {
  assistant: "#8B5CF6::shape_0", // violet hex
  "market-researcher": "#06B6D4::shape_4", // cyan pebble
  cfo: "#10B981::shape_2", // green squircle
  github: "#64748B::shape_1", // slate wedge
  neatlogs: neatlogsLogo, // Neatlogs "nl" mark, bundled as a data: URI
  "customer-success": "#F59E0B::shape_5", // amber blob
  legal: "#6366F1::shape_7", // indigo cloud
  hr: "#EC4899::shape_6", // pink teardrop
  marketing: "#F97316::shape_4", // orange pebble
  sales: "#14B8A6::shape_0", // teal hex
};

export function agentAvatarValue(agentId: string): string {
  const curated = CURATED[agentId];
  if (curated) return curated;
  const color = resolvePersonaColorDef(agentId).hex;
  const shape = shippedHash(agentId) % SHIPPED_BOT_AVATAR_SHAPE_KEYS.length;
  return `${color}::shape_${shape}`;
}
