}

export function Nav({ page }: { page: "home" | "judges" }) {
  const base = page === "home" ? "" : "/";
  const links = [
    { href: `${base}#how`, label: "How it works" },
    { href: `${base}#proof`, label: "Proof" },
    { href: `${base}#video`, label: "Video" },
  ];
  return (
    <header className="sticky top-0 z-40 border-b border-line/70 bg-bg/80 backdrop-blur-md supports-[not(backdrop-filter:blur(1px))]:bg-bg">
      <a
        href="#main"
        className="sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-3 focus:rounded-md focus:bg-card focus:px-3 focus:py-2"
      >
        Skip to content
      </a>
      <Container className="flex h-16 items-center justify-between gap-4">
        <Wordmark />
        <nav aria-label="Main" className="flex items-center gap-1">
          <ul className="hidden items-center gap-1 md:flex">
            {links.map((l) => (
              <li key={l.href}>
                <a
                  href={l.href}
                  className="rounded-full px-3 py-2 text-sm text-muted-fg transition-colors hover:text-fg"
                >
                  {l.label}
                </a>
              </li>
            ))}
          </ul>
          <a
            href="/judges/"
            aria-current={page === "judges" ? "page" : undefined}
            className={cx(
              "ml-2 inline-flex h-9 items-center rounded-full px-4 text-sm font-medium transition-colors",
              page === "judges"
                ? "border border-line bg-accent text-fg"
                : "bg-primary text-primary-fg hover:opacity-90",
            )}
          >
            For judges
          </a>
        </nav>
      </Container>
    </header>
  );
}

export function Footer() {
  return (
    <footer className="border-t border-line py-12 text-sm text-muted-fg">
      <Container className="flex flex-col gap-6 sm:flex-row sm:items-start sm:justify-between">
        <div className="max-w-md space-y-2">
          <Wordmark />
          <p>Built for {site.hackathon}.</p>
          <p>{site.credits}</p>
        </div>
        <ul className="flex flex-col gap-2 sm:items-end">
          <li>
            Source code: <ExtLink href={site.repoUrl}>GitHub repo</ExtLink>
          </li>
          <li>
            <a href="/judges/" className="text-fg underline-offset-4 hover:underline">
              Evidence for judges
            </a>
          </li>
        </ul>
      </Container>
    </footer>
  );
}
import type { ReactNode } from "react";
import { isTodo, type Maybe } from "../content";

export function cx(...parts: (string | false | null | undefined)[]) {
  return parts.filter(Boolean).join(" ");
}

/** Muted pill shown wherever content.ts still has a placeholder. */
export function Soon({ note, className }: { note?: string; className?: string }) {
  return (
    <span
      title={note}
      className={cx(
        "inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border border-dashed border-line bg-muted px-2.5 py-0.5 text-xs font-medium text-muted-fg",
        className,
      )}
    >
      <span aria-hidden className="size-1.5 rounded-full bg-muted-fg/60" />
      Coming soon
    </span>
  );
}

/** Renders a value, or the Coming soon pill if it is still a placeholder. */
export function Show<T>({
  value,
  children,
  className,
}: {
  value: Maybe<T>;
  children?: (v: T) => ReactNode;
  className?: string;
}) {
  if (isTodo(value)) return <Soon note={value.todo} className={className} />;
  return <>{children ? children(value) : String(value)}</>;
}

export function ExtLink({
  href,
  children,
  className,
}: {
  href: Maybe<string>;
  children: ReactNode;
  className?: string;
}) {
  if (isTodo(href)) return <Soon note={href.todo} className={className} />;
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer"
      className={cx("font-medium text-link underline-offset-4 hover:underline", className)}
    >
      {children}
    </a>
  );
}

export function Container({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cx("mx-auto w-full max-w-6xl px-4 sm:px-6", className)}>{children}</div>;
}

export function Section({
  id,
  title,
  intro,
  children,
  className,
}: {
  id?: string;
  title: string;
  intro?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  const headingId = id ? `${id}-title` : undefined;
  return (
    <section id={id} aria-labelledby={headingId} className={cx("py-20 sm:py-28", className)}>
      <Container>
        <h2
          id={headingId}
          className="max-w-3xl text-3xl font-semibold tracking-[-0.03em] text-balance sm:text-[2.75rem] sm:leading-[1.08]"
        >
          {title}
        </h2>
        {intro && <p className="mt-4 max-w-[62ch] text-lg text-muted-fg text-pretty">{intro}</p>}
        <div className="mt-12">{children}</div>
      </Container>
    </section>
  );
}

export function Button({
  href,
  children,
  variant = "primary",
  icon,
}: {
  href: string;
  children: ReactNode;
  variant?: "primary" | "ghost";
  icon?: ReactNode;
}) {
  return (
    <a
      href={href}
      className={cx(
        "inline-flex h-11 items-center gap-2 rounded-full px-5 text-[15px] font-medium transition-colors duration-150",
        variant === "primary"
          ? "bg-primary text-primary-fg hover:opacity-90"
          : "border border-line bg-card text-fg hover:bg-accent",
      )}
    >
      {icon}
      {children}
    </a>
  );
}
