from pathlib import Path
import struct,json
root=Path('site/public/evidence/2026-10-12')
sizes={}
for p in sorted(root.glob('*.png')):
    header=p.read_bytes()[:24]
    assert header[:8]==b'\x89PNG\r\n\x1a\n'
    w,h=struct.unpack('>II',header[16:24])
